import React, { Component } from "react";
//import FormattedMessage for translations
import { FormattedMessage } from "react-intl";
//import Loader
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import Loader from "react-loader-spinner";

//redux imports
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import { fetchMasterPOSacquirerSummaryItem, downloadMastercardPosAcquirerPostingCsv } from "../../../actions/filesets";

//utitity function to loop through and get headers
// import { setTableHeader } from '../../../Utils/utilityFunctions';
import { Button, Card, CardBody, CardHeader, Col, Row, Table } from "reactstrap";

//compononents to display table
import PostingTable from "../../../components/PostingTable";
import PostingTableHeader from "../../../components/PostingTableHeader";

class MastercardPosAcquirerSummaryDetail extends Component {
	constructor (props) {
		super(props);

		this.state = {};
	}

	componentDidMount () {
		const { fetchMasterPOSacquirerSummaryItem } = this.props;
		fetchMasterPOSacquirerSummaryItem(this.props.match.params.date);
	}
	//this refreshes the data with new content should incase the date is changed from the url
	componentDidUpdate (prevProps) {
		const { fetchMasterPOSacquirerSummaryItem } = this.props;
		if (prevProps.match.params.date !== this.props.match.params.date) {
			fetchMasterPOSacquirerSummaryItem(this.props.match.params.date);
		}
	}

	downloadMastercardAcquirerPostingCsv = (date) => {
		const { downloadMastercardPosAcquirerPostingCsv } = this.props;
		downloadMastercardPosAcquirerPostingCsv(date);
	};
	render () {
		//fetchMasterPOSacquirerSummaryItem
		const { MastercardAcquirerSummaryItem } = this.props;
		// if (MastercardAcquirerSummaryItem !== undefined && MastercardAcquirerSummaryItem.length !== 0) {
		// 	MastercardAcquirerSummaryItem.map((items) => {
		// 		// console.log(setTableHeader(items.records))
		// 	});
		// }

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						<Card>
							<CardHeader>
								<i className='fa fa-table' aria-hidden='true' />
								<FormattedMessage
									id=' POS-Acquirer Posting Summary'
									defaultMessage='POS-Acquirer Posting Summary Table'
								/>
								{MastercardAcquirerSummaryItem ? MastercardAcquirerSummaryItem.length !== 0 ? (
									<div className={"d-flex w-14 justiy-content-end float-right"}>
										<React.Fragment>
											<Button
												className={"float-right mb-0 btn-sm btn-block mx-1"}
												color='success'
												onClick={(e) =>
													this.downloadMastercardAcquirerPostingCsv(
														this.props.match.params.date,
													)}
											>
												<span
													className={"d-flex px-2 justify-content-center align-items-center"}
												>
													<i className='fa fa-download' />&nbsp;
													{this.props.fileSets.download_status ? (
														<Loader
															type='ThreeDots'
															color='#FFF'
															height={30}
															width={30}
															style={{ textAlign: "center" }}
														/>
													) : (
														<FormattedMessage
															id='Download CSV'
															defaultMessage='Download CSV'
														/>
													)}
												</span>
											</Button>
										</React.Fragment>
									</div>
								) : (
									""
								) : (
									""
								)}
							</CardHeader>
							<CardBody>
								{/*Display Table  */}
								{MastercardAcquirerSummaryItem ? (
									<Table
										hover
										bordered
										striped
										responsive
										size='sm'
										className='table-outline mb-0 d-sm-table'
										style={{ minWidth: "280%", textTransform: "capitalize" }}
									>
										<thead className='thead-light'>
											<PostingTableHeader />
										</thead>
										<tbody>
											<PostingTable
												tableName='masterCardPOS-AcquirerPostingSummary'
												dataRecords={MastercardAcquirerSummaryItem}
											/>
										</tbody>
									</Table>
								) : (
									<article className='d-flex justify-content-center align-items-center'>
										<Loader
											type='ThreeDots'
											color='#00BFFF'
											height={100}
											width={100}
											style={{ textAlign: "center" }}
										/>
									</article>
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}
const mapStateToProps = (state) => {
	return {
		MastercardAcquirerSummaryItem : state.fileSets.MastercardposAcquirerSummaryItem,
		fileSets                      : state.fileSets,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchMasterPOSacquirerSummaryItem,
			downloadMastercardPosAcquirerPostingCsv,
		},
		dispatch,
	);
};
export default connect(mapStateToProps, mapDispatchToProps)(MastercardPosAcquirerSummaryDetail);
